40	// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
41	// success; on failure prints an error tagged with `ctx` and returns "". The
42	// existence check is here, at the one resolver fast/cycle/cycle-gdb share, so a
43	// missing path fails with a clear "ELF not found" instead of being handed to the
44	// engine (e.g. qemu's cryptic "Unable to find the RISC-V BIOS"). Mirrors the
45	// up-front check run_hybrid already does.
46	std::string abs_elf(const std::string& path, const std::string& ctx) {
47	  std::error_code ec;
48	  fs::path abs = fs::absolute(path, ec);
49	  if (ec) {
50	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
51	                 ctx.c_str(), path.c_str());
52	    return "";
53	  }
54	  if (!fs::is_regular_file(abs, ec)) {
55	    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
56	                 path.c_str());
57	    return "";
58	  }
59	  return abs.string();
60	}
