123	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
124	// then run the resolved engine standalone with `extra` (model flags the
125	// framework forwards, e.g. fast's -m) followed by the post-`--` args verbatim.
126	// `clean_output` picks how the engine's output is presented: fast inherits the
127	// stdio transparently (exec_passthrough -- an interactive gdbstub / monitor /
128	// semihosting console works unchanged); cycle filters out the engine's banner +
129	// [info] noise and restates the cycle count (run_cycle_clean). Either way the
130	// exit code propagates. The per-model engine + selection are resolved by the
131	// caller; `model` here only labels the positional diagnostics.
132	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
133	                   const char* model, const std::vector<std::string>& extra = {},
134	                   bool clean_output = false) {
135	  if (int rc = check_one_elf(cli, model)) return rc;
136	  // QEMU's -bios flag searches its data directory for relative paths rather
137	  // than the CWD; resolve to absolute so the engine finds the ELF.
138	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
139	  if (elf.empty()) return 2;
140	  // `extra` (framework flags, e.g. fast's -m) precedes the post-`--` args, so a
141	  // user's own flag after `--` wins.
142	  std::vector<std::string> args = extra;
143	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
144	  std::string err;
145	  const std::vector<std::string> argv =
146	      passthrough_argv(eng, "standalone", elf, args, err);
147	  if (!err.empty()) {
148	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
149	    return 2;
150	  }
151	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
152	  // full qemu/vsim command (incl. -bios <elf> and any post-`--`).
153	  if (cli.dry_run)
154	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
155	  return clean_output ? run_cycle_clean(argv) : exec_passthrough(argv);
156	}
