188	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
189	// its --jtag-port only after it has reset and halted the hart, so the debugger we
190	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
191	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
192	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
193	// single debugger slot). Returns false on timeout.
194	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
195	  constexpr int kPollMs = 50;
196	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
197	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
198	      char line[512];
199	      while (std::fgets(line, sizeof line, f)) {
200	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
201	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
202	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
203	        unsigned lport = 0, st = 0;
204	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
205	            && st == 0x0A && lport == port) {
206	          std::fclose(f);
207	          return true;
208	        }
209	      }
210	      std::fclose(f);
211	    }
212	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
213	  }
214	  return false;
215	}
