217	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
218	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
219	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
220	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
221	  const char* iceman = std::getenv("ICEMAN");
222	  if (!iceman || !*iceman) {
223	    std::fprintf(stderr,
224	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
225	                 "(export ICEMAN=<path to ICEman binary>)\n");
226	    return 2;
227	  }
228	  // Build vsim argv from the standalone template, appending user passthrough
229	  // and the JTAG port flag.
230	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
231	  if (elf.empty()) return 2;
232	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
233	  std::vector<std::string> vsim_pass = cli.passthrough;
234	  vsim_pass.push_back("--jtag-port");
235	  vsim_pass.push_back(jtag_port);
236	  std::string err;
237	  const std::vector<std::string> vsim_argv =
238	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
239	  if (!err.empty()) {
240	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
241	    return 2;
242	  }
243	  std::fprintf(stderr,
244	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
245	               jtag_port.c_str());
246	  if (fork_background(vsim_argv) < 0) {
247	    std::fprintf(stderr,
248	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
249	    return 1;
250	  }
251	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
252	  // Wait for the port to be LISTENing before launching the debugger (it does not
253	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
254	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
255	  // but launch anyway if it never appears.
256	  if (const int pnum = std::atoi(jtag_port.c_str());
257	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
258	    std::fprintf(stderr,
259	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
260	                 "after 20s; launching the debugger anyway\n",
261	                 jtag_port.c_str());
262	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
263	  // localhost, port 9104) instead of its default real-hardware adapter; without
264	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
265	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
266	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
267	}
