275	  // --describe subprocess per vsim build only to fail on the argument.
276	  if (int rc = check_one_elf(cli, "cycle")) return rc;
277	  // --mem-size is validated but has nothing to size: the cycle engine always
278	  // models its full DRAM window. Say so instead of silently ignoring it.
279	  if (!cli.mem_size.empty()) {
280	    std::string se;
281	    if (parse_size(cli.mem_size, se); !se.empty()) {
282	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
283	                   se.c_str());
