310	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
311	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
312	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
313	// driver's tests/e2e.sh delegation with a single window-cycle line.
314	int run_hybrid(const Cli& cli) {
315	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
316	  auto fail = [](const std::string& msg) {
317	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
318	    return 2;
319	  };
320	
321	  if (int rc = check_one_elf(cli, "hybrid")) return rc;
322	
323	  // Resolve to an absolute, existing ELF through the shared resolver -- the same
324	  // check and "ELF not found" message fast/cycle get (abs_elf already printed on
325	  // failure). pc-trigger resolution below then reads the ELF's .symtab.
326	  const std::string elf_path = abs_elf(cli.positional[0], "--mode hybrid");
327	  if (elf_path.empty()) return 2;
328	  const fs::path elf{elf_path};  // for .stem() in the banner / PASS lines
329	
330	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
331	  // mistake fails fast without spawning a --describe per Verilator build.
332	  std::string err;
333	  const Trigger trig = hybrid_trigger(cli, elf_path, err);
334	  if (!err.empty()) return fail(err);
335	
336	  std::vector<std::string> vsim_extras = vsim_extra_args(cli, trig.kind, err);
337	  if (!err.empty()) return fail(err);
338	
339	  long long mem = 128LL * 1024 * 1024;  // shared mmap; --mem-size overrides
340	  if (!cli.mem_size.empty()) {
341	    std::string se;
342	    mem = parse_size(cli.mem_size, se);
343	    if (!se.empty()) return fail("--mem-size: " + se);
344	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the mmap backend doubles
345	    // as guest RAM here. Failing now beats allocating a huge mmap file first and
346	    // letting QEMU die late.
347	    if (mem > 2LL * 1024 * 1024 * 1024)
348	      return fail("--mem-size " + cli.mem_size +
349	                  " exceeds the AE350 DRAM window (2G)");
350	  }
351	
352	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
353	  // or the sole cycle-accurate engine (reusing the F8 selector).
354	  Discovery disc = discover_engines();
355	  const EngineDescriptor* acc =
356	      resolve_accurate_engine(disc.engines, cli.engine, err);
357	  if (!acc) {
358	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
359	    for (const std::string& w : disc.warnings)
360	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
361	    return 2;
362	  }
363	
364	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
365	  // cannot share architectural state with the rv64 fast leg).
366	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
367	
368	  Plan plan;
369	  plan.elf = elf_path;
370	  plan.mem_size = mem;
371	  Step qemu_step{kQemuId, "fast-leg", trig};
372	  Step vsim_step{acc->id, "accurate-leg", trig};
373	  vsim_step.extra_args = std::move(vsim_extras);  // kanata, validated
374	  // The driver consumes only the vsim mcycle delta, so ask the accurate leg to
375	  // drain just the counters and skip the full register-file readback (~190 DM
376	  // abstract commands). Policy lives here at the Step-construction site, not in
377	  // vsim_extra_args (scoped to user-forwarded, trigger-validated flags).
378	  vsim_step.extra_args.push_back("--drain-minimal");
379	  plan.steps = {qemu_step, vsim_step};
380	
381	  // Banner to stderr so the window-cycle result stands alone on stdout.
382	  // vlen is the synced value the fast leg inherits from the engine.
383	  std::fprintf(stderr,
384	               "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s\n",
385	               acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
386	               elf.stem().string().c_str());
387	
388	  PlanOptions opts;
389	  opts.dry_run = cli.dry_run;
390	  const PlanResult r = run_plan(plan, disc.engines, opts);
391	  if (!r.ok()) {
392	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
393	    return 1;
394	  }
395	  // --dry-run: print the exact per-leg commands run_plan assembled -- the QEMU
396	  // fast leg (incl. the staged -readconfig from the engine's --print-qemu-config)
397	  // then the vsim accurate leg -- and stop. Nothing was spawned.
398	  if (cli.dry_run) {
399	    std::vector<std::string> labels;
400	    labels.reserve(plan.steps.size());
401	    for (const Step& s : plan.steps)
402	      labels.push_back(s.role + " [" + s.engine_id + "]");
403	    return print_dry_run(r.argvs, labels);
404	  }
405	  // Relay each leg's stdout: the program's own prints (QEMU1 phase-1 output,
406	  // then anything the ROI wrote on vsim) belong to the user. The vsim
407	  // (accurate) leg's output is prefixed by vsim's startup banner (Copyright /
408	  // Version) -- strip it so only real program output shows, the same as `cycle`
409	  // does; its [info] log is already absent (the leg's stderr was dropped at
410	  // capture). The QEMU leg has no banner, so it relays verbatim.
411	  for (size_t i = 0; i < r.phases.size(); ++i) {
412	    const std::string& out = r.phases[i].out;
413	    if (out.empty()) continue;
414	    if (i < plan.steps.size() && plan.steps[i].role == "accurate-leg") {
415	      const std::string shown = strip_vsim_banner(out);
416	      std::fwrite(shown.data(), 1, shown.size(), stdout);
417	    } else {
418	      std::fwrite(out.data(), 1, out.size(), stdout);
419	    }
420	  }
421	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
422	  // vsim mcycle delta.
423	  const unsigned long long q_mc = r.phases[0].mcycle;
424	  const unsigned long long v_mc = r.phases[1].mcycle;
425	  std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
426	              trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
427	  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
428	              elf.stem().string().c_str());
429	  return 0;
430	}
