434	int cmd_run(const Cli& cli) {
435	  if (cli.model.empty()) {
436	    std::fprintf(stderr,
437	                 "andesim run: --mode fast|cycle|hybrid is required "
438	                 "(pick the composition; see 'andesim run --help')\n");
439	    return 2;
440	  }
441	  if (!find_model(cli.model)) {
442	    std::fprintf(stderr,
443	                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
444	                 cli.model.c_str());
445	    return 2;
446	  }
447	  if (!cli.gdb_port.empty() && !cli.gdb) {
448	    std::fprintf(stderr, "andesim run: --gdb-port requires --gdb\n");
449	    return 2;
450	  }
451	  // --gdb is an interactive debugging aid; the hybrid handoff runs QEMU1 then
452	  // vsim sequentially in a pipeline and cannot pause for a debugger to attach.
453	  if (cli.gdb && cli.model == "hybrid") {
454	    std::fprintf(stderr,
455	                 "andesim run: --gdb is not supported with --mode hybrid\n");
456	    return 2;
457	  }
458	  // Post-`--` args are forwarded verbatim to the engine -- but hybrid has TWO
459	  // legs (a QEMU fast-forward + a vsim measure leg) whose command lines the
460	  // handoff builds itself, so there is no single "the engine" to forward to.
461	  // Reject rather than silently drop (the old behavior) or guess a leg. vsim
462	  // options have dedicated flags (--kanata/--objdump); fast/cycle still forward.
463	  if (!cli.passthrough.empty() && cli.model == "hybrid") {
464	    std::fprintf(stderr,
465	                 "andesim run: --mode hybrid takes no `-- <args>` (the handoff "
466	                 "builds both legs' command lines; use --kanata/--objdump for "
467	                 "vsim options, or --mode fast|cycle to forward to one engine)\n");
468	    return 2;
469	  }
470	  // --trigger / --pc-start / --pc-end delimit the hybrid ROI window. --trigger
471	  // is hybrid-only; --pc-start/--pc-end belong to --trigger pc specifically. Any
472	  // other mode/trigger would SILENTLY drop them and hand back a figure for the
473	  // wrong window (fast/cycle: the whole program; hybrid+marker: the marker
474	  // window), so reject instead of measuring something the user did not ask for.
475	  if (!cli.trigger.empty() && cli.model != "hybrid") {
476	    std::fprintf(stderr,
477	                 "andesim run: --trigger applies only to --mode hybrid "
478	                 "(the ROI delimiter); fast/cycle run the whole program\n");
479	    return 2;
480	  }
481	  if (!cli.pc_end.empty() && cli.trigger != "pc") {
482	    std::fprintf(stderr,
483	                 "andesim run: --pc-end applies only to --mode hybrid "
484	                 "--trigger pc\n");
485	    return 2;
486	  }
487	  if (!cli.pc_start.empty() && cli.trigger != "pc") {
488	    std::fprintf(stderr,
489	                 "andesim run: --pc-start applies only to --mode hybrid "
490	                 "--trigger pc\n");
491	    return 2;
492	  }
493	  if (cli.model == "fast") return run_fast(cli);
494	  if (cli.model == "cycle") return run_accurate(cli);
495	  return run_hybrid(cli);  // model validated above; only hybrid remains
496	}
