36	// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
37	// success; on failure prints an error tagged with `ctx` and returns "". The
38	// existence check lives here, at the one resolver fast/cycle/hybrid share, so a
39	// missing path fails with a clear "ELF not found" in the driver instead of being
40	// handed to the engine (e.g. qemu's cryptic "Unable to find the RISC-V BIOS").
41	std::string abs_elf(const std::string& path, const std::string& ctx) {
42	  std::error_code ec;
43	  fs::path abs = fs::absolute(path, ec);
44	  if (ec) {
45	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
46	                 ctx.c_str(), path.c_str());
47	    return "";
48	  }
49	  if (!fs::is_regular_file(abs, ec)) {
50	    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
51	                 path.c_str());
52	    return "";
53	  }
54	  return abs.string();
55	}
