57	// Validate the lone-ELF positional shape the standalone models require: print
58	// the diagnostic and return 2 on a violation, else 0. `model` labels the error.
59	int check_one_elf(const Cli& cli, const char* model) {
60	  if (cli.positional.empty()) {
61	    std::fprintf(stderr,
62	                 "andesim run --mode %s: missing ELF (the workload to run; "
63	                 "e.g. a tests/fixtures/<name>.elf)\n",
64	                 model);
65	    return 2;
66	  }
67	  if (cli.positional.size() > 1) {
68	    std::fprintf(stderr,
69	                 "andesim run --mode %s: unexpected argument '%s' "
70	                 "(engine args go after --)\n",
71	                 model, cli.positional[1].c_str());
72	    return 2;
73	  }
74	  return 0;
75	}
