78	// shell-quoted and labeled, executing nothing. Shared by every --mode so the
79	// preview format is identical; `labels[i]` annotates `argvs[i]` (e.g.
80	// "fast-leg [qemu]", "standalone [qemu]"). Always returns 0 -- a dry run
81	// reports the plan, it does not run it.
82	int print_dry_run(const std::vector<std::vector<std::string>>& argvs,
83	                  const std::vector<std::string>& labels) {
84	  std::printf("[andesim] dry-run: %zu command(s), not executed\n", argvs.size());
85	  for (size_t i = 0; i < argvs.size(); ++i) {
86	    std::printf("# command %zu/%zu: %s\n", i + 1, argvs.size(),
