93	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
94	// then run the resolved engine standalone with `extra` framework-injected args
95	// (e.g. fast's --mem-size `-m`) followed by the post-`--` args forwarded
96	// verbatim, inheriting stdio (an interactive gdbstub / monitor / semihosting
97	// console works unchanged) and propagating the exit code. `extra` precedes the
98	// user's passthrough so a user's own flag wins. The per-model engine +
99	// selection are resolved by the caller; `model` here only labels the positional
100	// diagnostics. The ELF is resolved to an absolute, existing path (abs_elf) so a
101	// missing file fails here in the driver, not later inside the engine.
102	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
103	                   const char* model, const std::vector<std::string>& extra = {}) {
104	  if (int rc = check_one_elf(cli, model)) return rc;
105	  // QEMU's -bios flag searches its data directory for relative paths rather than
106	  // the CWD; resolving to absolute (and rejecting a missing file) makes both
107	  // QEMU and vsim find the ELF, and fails a typo with a clear "ELF not found".
108	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
109	  if (elf.empty()) return 2;
110	  std::vector<std::string> args = extra;
111	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
112	  std::string err;
113	  const std::vector<std::string> argv =
114	      passthrough_argv(eng, "standalone", elf, args, err);
115	  if (!err.empty()) {
116	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
117	    return 2;
118	  }
119	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
120	  // full qemu/vsim standalone command (incl. -bios <elf> and any post-`--`).
121	  if (cli.dry_run)
122	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
123	  return exec_passthrough(argv);
124	}
