126	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Resolves
127	// the built-in qemu descriptor directly (no engine discovery -- fast needs only
128	// qemu, and discover_engines would spawn a --describe per Verilator build).
129	int run_fast(const Cli& cli) {
130	  // fast is QEMU-only; an explicit engine must name it.
131	  if (!cli.engine.empty() && cli.engine != "qemu") {
132	    std::fprintf(stderr,
133	                 "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
134	                 cli.engine.c_str());
135	    return 2;
136	  }
137	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
138	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
139	  std::string err;
140	  std::vector<std::string> extra = qemu_m_args(cli.mem_size, err);
141	  if (!err.empty()) {
142	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
143	    return 2;
144	  }
145	  // --gdb: launch QEMU with its built-in gdbstub, frozen at reset, so a gdb
146	  // client can attach before the first instruction retires. -gdb tcp::PORT
147	  // opens the stub (--gdb-port overrides the 1234 default); -S halts the CPU at
148	  // startup. These precede the post-`--` args, so an explicit user override
149	  // still wins.
150	  if (cli.gdb) {
151	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
152	    extra.push_back("-gdb");
153	    extra.push_back("tcp::" + port);
154	    extra.push_back("-S");
155	  }
156	  return run_standalone(cli, builtin_qemu(), "fast", extra);
157	}
