159	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
160	// its --jtag-port only after it has reset and halted the hart, so the debugger we
161	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
162	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
163	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
164	// single debugger slot). Returns false on timeout.
165	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
166	  constexpr int kPollMs = 50;
167	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
168	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
169	      char line[512];
170	      while (std::fgets(line, sizeof line, f)) {
171	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
172	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
173	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
174	        unsigned lport = 0, st = 0;
175	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
176	            && st == 0x0A && lport == port) {
177	          std::fclose(f);
178	          return true;
179	        }
180	      }
181	      std::fclose(f);
182	    }
183	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
184	  }
185	  return false;
186	}
