188	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
189	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
190	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
191	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
192	  const char* iceman = std::getenv("ICEMAN");
193	  if (!iceman || !*iceman) {
194	    std::fprintf(stderr,
195	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
196	                 "(export ICEMAN=<path to ICEman binary>)\n");
197	    return 2;
198	  }
199	  // Build vsim argv from the standalone template, appending user passthrough
200	  // and the JTAG port flag.
201	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
202	  if (elf.empty()) return 2;
203	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
204	  std::vector<std::string> vsim_pass = cli.passthrough;
205	  vsim_pass.push_back("--jtag-port");
206	  vsim_pass.push_back(jtag_port);
207	  std::string err;
208	  const std::vector<std::string> vsim_argv =
209	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
210	  if (!err.empty()) {
211	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
212	    return 2;
213	  }
214	  std::fprintf(stderr,
215	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
216	               jtag_port.c_str());
217	  if (fork_background(vsim_argv) < 0) {
218	    std::fprintf(stderr,
219	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
220	    return 1;
221	  }
222	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
223	  // Wait for the port to be LISTENing before launching the debugger (it does not
224	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
225	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
226	  // but launch anyway if it never appears.
227	  if (const int pnum = std::atoi(jtag_port.c_str());
228	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
229	    std::fprintf(stderr,
230	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
231	                 "after 20s; launching the debugger anyway\n",
232	                 jtag_port.c_str());
233	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
234	  // localhost, port 9104) instead of its default real-hardware adapter; without
235	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
236	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
237	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
238	}
