240	// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
241	// no --resume-from-qemu), transparent passthrough -- cycles surface in the
242	// engine's own output. Unlike fast, this must discover the Verilator build(s)
243	// to resolve the engine (explicit --engine, else the sole one).
244	int run_accurate(const Cli& cli) {
245	  // Reject a missing/extra ELF before discovery so a CLI typo does not spawn a
246	  // --describe subprocess per Verilator build only to fail on the argument.
247	  if (int rc = check_one_elf(cli, "cycle")) return rc;
248	  // --mem-size is validated but has nothing to size: the cycle engine always
249	  // models its full DRAM window. Say so instead of silently ignoring it.
250	  if (!cli.mem_size.empty()) {
251	    std::string se;
252	    if (parse_size(cli.mem_size, se); !se.empty()) {
253	      std::fprintf(stderr, "andesim run --mode cycle: --mem-size: %s\n",
254	                   se.c_str());
255	      return 2;
256	    }
257	    std::fprintf(stderr,
258	                 "[andesim] --mem-size: the cycle engine models its full "
259	                 "DRAM window; nothing to size\n");
260	  }
261	  Discovery disc = discover_engines();
262	  std::string err;
263	  const EngineDescriptor* eng =
264	      resolve_accurate_engine(disc.engines, cli.engine, err);
265	  if (!eng) {
266	    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
267	    // Surface why an expected engine may be absent (failed --describe, etc.).
268	    for (const std::string& w : disc.warnings)
269	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
270	    return 2;
271	  }
272	  // --dry-run previews the standalone command and spawns nothing, so it takes
273	  // precedence over the interactive --gdb path (a dry run launches no debugger).
274	  if (cli.gdb && !cli.dry_run) return run_cycle_gdb(cli, *eng);
275	  return run_standalone(cli, *eng, "cycle");
276	}
