391	  // handoff builds itself, so there is no single "the engine" to forward to.
392	  // Reject rather than silently drop (the old behavior) or guess a leg. vsim
393	  // options have dedicated flags (--kanata/--objdump); fast/cycle still forward.
394	  if (!cli.passthrough.empty() && cli.model == "hybrid") {
